import { useCallback, useEffect, useState } from "react";

import {
  type ExerciseDraft,
  type RhythmPracticeSettings,
  generateRhythmExercise,
} from "@/lib/engine";

/** Settings that change what is generated (tempo does not). */
const generationKey = (s: RhythmPracticeSettings) =>
  JSON.stringify([s.difficulty, s.custom, s.customMode, s.written, s.timeSignature, s.bars]);

/** The current exercise (as a draft: a written rhythm may be unfinished).
 * Regenerated by the engine whenever a setting that affects it changes, or on
 * demand. */
export function useRhythmExercise(settings: RhythmPracticeSettings) {
  const [draft, setDraft] = useState<ExerciseDraft | null>(null);
  const [error, setError] = useState<string | null>(null);
  const key = generationKey(settings);

  const regenerate = useCallback(async () => {
    try {
      setDraft(await generateRhythmExercise());
      setError(null);
    } catch (e) {
      setDraft(null);
      setError(String(e));
    }
  }, []);

  // `key` changes only after the engine has saved the new settings, so the
  // engine generates from the values shown.
  useEffect(() => {
    regenerate();
  }, [key, regenerate]);

  return { draft, error, regenerate };
}
